                <div style={{ color: c.textPrimary, fontFamily: c.fontMono, fontSize: 14 }}>
                    <span style={{ color: accent, fontWeight: 700 }}>RGB out[y,x] = Σ625 K[i,j] · RGB in[y+i,x+j]</span>
                    <span style={{ color: c.textSecondary }}> · normalized weights sum to 1 across the 25 × 25 neighborhood</span>
                </div>
